# Printed on the front of every lending envelope so volunteers can shelve the lot.
def format_seed_label(lot):
    variety = lot['variety'].strip().title()
    return variety + ' (' + str(lot['harvest_year']) + ') - lot ' + str(lot['lot_number'])

# A germination trial plants a counted sample and records how many sprouted.
def seed_germination_rate(trial):
    planted = trial['planted']
    if planted <= 0:
        return 0.0
    return round(trial['sprouted'] / planted, 3)

# Each member may hold only a fixed number of borrowed lots; the balance is what is left.
def remaining_checkout_balance(member):
    remaining = member['borrowing_limit'] - len(member['open_loans'])
    return max(remaining, 0)

# Loans are due back after the growing season; the reminder goes out seven days early.
def days_until_overdue_reminder(loan):
    return max(loan['days_until_due'] - 7, 0)

# Stock stored above sixty percent relative humidity loses vigor within a season.
def humidity_exceeds_threshold(reading):
    return reading['relative_humidity'] > 60

# Donors spell variety names many ways; intake keeps one normalized spelling.
def normalize_donor_variety_name(name):
    words = name.replace('_', ' ').replace('-', ' ').split()
    return ' '.join(word.capitalize() for word in words)

# Monthly volunteer report: how many lots sit on the shelf for each plant family.
def summarize_inventory_by_family(stock):
    counts = {}
    for lot in stock:
        counts[lot['family']] = counts.get(lot['family'], 0) + 1
    return dict(sorted(counts.items()))

# Planning aid: which packets stay inside their viability window through next year.
def forecast_viable_packets(packets):
    return [p for p in packets if p['harvest_year'] + p['viability_years'] > p['current_year']]

